package app.eversage.offline;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.provider.MediaStore;import android.text.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;
import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Native Android Views only. No WebView, HTML, JavaScript or hosted app. */
public class NativeActivity extends Activity {
 static final int PAPER=Color.rgb(255,252,246),INK=Color.rgb(57,44,37),ORANGE=Color.rgb(184,70,30),MUTED=Color.rgb(116,96,81),LINE=Color.rgb(230,214,200),SOFT=Color.rgb(248,231,216);
 LinearLayout root,body;ScrollView scroll;EditText editor;SharedPreferences prefs;ArrayList<JSONObject> cases=new ArrayList<>(),matches=new ArrayList<>();TreeSet<String> traditions=new TreeSet<>();HashSet<String> chosen=new HashSet<>(),saved=new HashSet<>();ArrayDeque<String> history=new ArrayDeque<>();ExecutorService worker=Executors.newSingleThreadExecutor();
 String page="home",category="career",problem="",focus="",tab="story";JSONObject current;boolean clarifying=false,artOn=true;float textScale=1;Bitmap card;ImageView cardPreview;byte[] pendingImage;
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}int wide(){return getResources().getConfiguration().screenWidthDp;}
 public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("eversage-native",0);chosen.addAll(prefs.getStringSet("traditions",new HashSet<>()));saved.addAll(prefs.getStringSet("saved",new HashSet<>()));textScale=prefs.getFloat("textScale",1);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  try(InputStream in=getAssets().open("episodes.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONArray a=new JSONObject(out.toString("UTF-8")).getJSONArray("episodes");for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i);cases.add(c);traditions.add(c.getString("tradition"));}}catch(Exception e){new AlertDialog.Builder(this).setTitle("Could not open the library").setMessage("Please close EverSage and open it again.").setPositiveButton("Close",(d,w)->finish()).show();return;}
  chosen.retainAll(traditions);if(state!=null){problem=state.getString("problem","");focus=state.getString("focus","");page=state.getString("page","home");category=state.getString("category","career");tab=state.getString("tab","story");current=findById(state.getString("case",""));if((page.equals("detail")||page.equals("source")||page.equals("share"))&&current==null)page="home";}if(getIntent().getBooleanExtra("daily",false))selectDaily(false);render();if(prefs.getBoolean("reminder",false))scheduleReminder(true,prefs.getString("time","08:00"));
 }
 protected void onSaveInstanceState(Bundle b){capture();b.putString("problem",problem);b.putString("focus",focus);b.putString("page",page);b.putString("category",category);b.putString("tab",tab);b.putString("case",current==null?"":current.optString("id"));super.onSaveInstanceState(b);}
 void capture(){if(editor!=null){problem=editor.getText().toString();editor=null;}}
 void go(String p){capture();history.push(page);page=p;hideKeyboard();render();}
 public void onBackPressed(){capture();if(history.isEmpty()){if(page.equals("home")){finish();return;}page="home";}else page=history.pop();hideKeyboard();render();}
 void hideKeyboard(){View f=getCurrentFocus();if(f!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(f.getWindowToken(),0);}
 GradientDrawable bg(int color,int stroke,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));if(stroke!=0)g.setStroke(dp(1),stroke);return g;}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);l.setOrientation(LinearLayout.HORIZONTAL);l.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));return l;}
 TextView text(String t,int size,boolean bold,int color){TextView v=new TextView(this);v.setText(t);v.setTextSize(size*textScale);v.setTextColor(color);v.setLineSpacing(dp(3),1.07f);v.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));v.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));return v;}
 void addText(String t,int size,boolean bold,int color){TextView v=text(t,size,bold,color);LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)v.getLayoutParams();lp.topMargin=dp(9);lp.bottomMargin=dp(9);body.addView(v);}
 void h1(String t){addText(t,27,true,INK);}void h2(String t){addText(t,20,true,INK);}void para(String t){addText(t,17,false,INK);}void small(String t){addText(t,13,false,MUTED);}
 void gap(int h){View v=new View(this);body.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
 void divider(){View v=new View(this);v.setBackgroundColor(LINE);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.topMargin=dp(15);p.bottomMargin=dp(12);body.addView(v,p);}
 Button button(String label,boolean primary,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(15*textScale);b.setTextColor(primary?Color.WHITE:ORANGE);b.setTypeface(Typeface.create("sans-serif-medium",0));b.setBackground(bg(primary?ORANGE:PAPER,primary?0:LINE,13));b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setMinHeight(dp(50));b.setMinimumHeight(dp(50));b.setMinWidth(0);b.setMinimumWidth(0);b.setMaxLines(2);b.setGravity(Gravity.CENTER);b.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);lp.bottomMargin=dp(4);b.setLayoutParams(lp);return b;}
 void action(String label,boolean primary,Runnable action){body.addView(button(label,primary,action));}
 void option(String title,String subtitle,Runnable click){LinearLayout l=vertical();l.setPadding(dp(14),dp(12),dp(14),dp(12));l.setBackground(bg(PAPER,LINE,13));l.setMinimumHeight(dp(58));l.setClickable(true);l.setFocusable(true);l.setContentDescription(title);l.addView(text(title,16,true,INK));if(subtitle!=null&&!subtitle.isEmpty()){TextView s=text(subtitle,13,false,MUTED);s.setPadding(0,dp(6),0,0);l.addView(s);}l.setOnClickListener(v->click.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);lp.bottomMargin=dp(3);body.addView(l,lp);}
 void image(String name,int height){ImageView im=new ImageView(this);try(InputStream in=getAssets().open("art/"+name+".webp")){im.setImageDrawable(Drawable.createFromStream(in,null));}catch(Exception ignored){}im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setContentDescription("Painted EverSage landscape");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(height));lp.topMargin=dp(8);lp.bottomMargin=dp(10);body.addView(im,lp);}
 void sourceLine(JSONObject c){small(c.optString("book")+" · "+c.optString("reference"));}
 void render(){editor=null;root=vertical();root.setBackgroundColor(PAPER);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);buildHeader();scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);body=vertical();body.setPadding(dp(20),dp(5),dp(20),dp(24));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  switch(page){case "home":home();break;case "examples":examples();break;case "write":write();break;case "clarify":clarify();break;case "results":results();break;case "detail":detail();break;case "source":source();break;case "traditions":traditionPicker();break;case "saved":saved();break;case "daily":daily();break;case "settings":settings();break;case "library":library();break;case "share":shareScreen();break;default:home();}
  buildBottom();root.requestApplyInsets();}
 void buildHeader(){LinearLayout top=row();top.setPadding(dp(12),dp(5),dp(12),dp(5));if(!page.equals("home")){Button back=button("‹",false,()->onBackPressed());back.setTextSize(26);back.setContentDescription("Back");top.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));}TextView title=text(page.equals("home")?"eversage":pageTitle(),page.equals("home")?28:18,true,page.equals("home")?ORANGE:INK);title.setPadding(dp(8),0,dp(8),0);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));if(page.equals("detail")||page.equals("daily")){Button s=button(current!=null&&saved.contains(current.optString("id"))?"Saved":"Save",false,()->toggleSave());s.setContentDescription("Save story");top.addView(s,new LinearLayout.LayoutParams(dp(74),-2));}else{Button s=button("⋮",false,()->go("settings"));s.setTextSize(23);s.setContentDescription("Settings");top.addView(s,new LinearLayout.LayoutParams(dp(48),dp(48)));}root.addView(top);}
 String pageTitle(){switch(page){case "examples":return categoryName();case "write":return "Your situation";case "clarify":return "A closer match";case "results":return "Matching stories";case "detail":return "Story & lesson";case "source":return "Source";case "traditions":return "Traditions";case "saved":return "Saved";case "daily":return "Daily wisdom";case "settings":return "Settings";case "library":return "Source library";case "share":return "Share";default:return "EverSage";}}
 void buildBottom(){LinearLayout nav=row();nav.setPadding(dp(12),dp(7),dp(12),dp(7));for(String[] a:new String[][]{{"Home","home"},{"Saved","saved"},{"Daily","daily"}}){Button b=button(a[0],false,()->{if(a[1].equals("daily"))selectDaily(false);history.clear();page=a[1];render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=dp(4);lp.rightMargin=dp(4);nav.addView(b,lp);}root.addView(nav);}
 String categoryName(){for(String[] c:SituationMatcher.CATEGORIES)if(c[0].equals(category))return c[1];return "Your situation";}
 String chosenLabel(){return chosen.isEmpty()?"All available traditions":chosen.size()+" selected";}
 void filter(){option("Traditions",chosenLabel(),()->go("traditions"));}
 void home(){h1("What are you facing?");small("Choose a problem or write your own.");image("home",wide()<350?145:180);action("Write it",true,()->{problem="";focus="";clarifying=false;go("write");});h2("Explore problems");for(String[] c:SituationMatcher.CATEGORIES){option(c[1],firstExample(c[0]),()->{category=c[0];clarifying=false;go("examples");});}filter();action("Sources",false,()->go("library"));}
 String firstExample(String cat){for(String[] p:SituationMatcher.PROBLEMS)if(p[0].equals(cat))return p[2];return "";}
 void examples(){h1(clarifying?"Which part fits?":"Choose what fits");if(clarifying&&!problem.isEmpty()){small("You wrote");para(problem);}for(String[] p:SituationMatcher.PROBLEMS)if(p[0].equals(category)){option(p[2],"",()->{focus=p[1];if(!clarifying)problem=p[2];go("results");});}action("Write my own",false,()->{focus="";go("write");});filter();}
 void write(){h1("What happened?");small("A few specific words help. For example: I lost my job, or I cannot choose a career.");editor=new EditText(this);editor.setText(problem);editor.setTextColor(INK);editor.setTextSize(18*textScale);editor.setGravity(Gravity.TOP);editor.setMinLines(4);editor.setMaxLines(7);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);editor.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1000)});editor.setPadding(dp(14),dp(13),dp(14),dp(13));editor.setBackground(bg(PAPER,LINE,12));editor.setHint("Tell us the part you want help with.");editor.setContentDescription("Your situation");body.addView(editor,new LinearLayout.LayoutParams(-1,-2));small("Your writing stays on this phone and is not saved as a history.");filter();action("Find wisdom",true,()->submit());}
 void submit(){capture();if(problem.trim().isEmpty()){new AlertDialog.Builder(this).setMessage("Write what happened, or choose an example.").setPositiveButton("OK",null).show();return;}if(SituationMatcher.urgent(problem)){new AlertDialog.Builder(this).setTitle("Your safety comes first").setMessage("If you are in immediate danger, contact local emergency services or a trusted person now. A story is not emergency help.").setPositiveButton("OK",null).show();return;}List<String> found=SituationMatcher.detect(problem);if(found.size()==1){focus=found.get(0);go("results");}else{focus="";go("clarify");}}
 void clarify(){h1("What should we focus on?");para(problem);List<String> found=SituationMatcher.detect(problem);if(!found.isEmpty()){small("More than one part may matter. Choose one for this answer.");for(String f:found)option(SituationMatcher.label(f),"",()->{focus=f;go("results");});}else small("I need a little more detail to choose a relevant story.");h2("Choose the area");for(String[] c:SituationMatcher.CATEGORIES)option(c[1],"",()->{category=c[0];clarifying=true;go("examples");});action("Edit",false,()->go("write"));}
 boolean supports(JSONObject c,String intent){JSONArray a=c.optJSONArray("intents");for(int i=0;a!=null&&i<a.length();i++)if(a.optString(i).equals(intent))return true;return false;}
 void results(){h1("A story that fits");if(focus.equals("family_repair")){para("Which part needs repair?");for(String[] a:new String[][]{{"I caused harm","regret"},{"They hurt me","betrayal"},{"We keep arguing","argument"}})action(a[0],false,()->{focus=a[1];render();});return;}small("Your situation");para(problem);filter();matches.clear();for(JSONObject c:cases)if(supports(c,focus)&&(chosen.isEmpty()||chosen.contains(c.optString("tradition"))))matches.add(c);
  if(matches.isEmpty()){h2("No close match yet");para("I do not have a checked episode for this exact part in the selected sources. I will not replace it with a random quote.");if(focus.equals("romantic_loss")){small("Which part of the breakup would you like wisdom for?");for(String[] a:new String[][]{{"Broken trust","betrayal"},{"Missing them","grief_separation"},{"Feeling lesser","feeling_inferior"},{"Fear ahead","fear_ahead"}})action(a[0],false,()->{focus=a[1];render();});}else{action("Add detail",true,()->go("clarify"));}if(!chosen.isEmpty())action("All traditions",false,()->{chosen.clear();prefs.edit().putStringSet("traditions",new HashSet<>(chosen)).apply();render();});return;}
  small(matches.size()+" relevant source"+(matches.size()==1?"":"s")+". The parallel is explained before you choose.");for(JSONObject c:matches){LinearLayout card=vertical();card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(bg(PAPER,LINE,16));card.addView(text(c.optString("tradition"),12,true,ORANGE));TextView t=text(c.optString("title"),20,true,INK);t.setPadding(0,dp(9),0,dp(8));card.addView(t);card.addView(text(c.optString("why"),15,false,MUTED));TextView src=text(c.optString("book")+" · "+c.optString("reference"),12,false,ORANGE);src.setPadding(0,dp(11),0,dp(5));card.addView(src);Button read=button("Read story",true,()->{current=c;tab="story";go("detail");});read.setContentDescription("Read story: "+c.optString("id"));card.addView(read);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(16);body.addView(card,lp);}}
 void tabs(){LinearLayout l=row();for(String[] a:new String[][]{{"Story","story"},{"Lesson","lesson"},{"Try this","step"}}){Button b=button(a[0],tab.equals(a[1]),()->{tab=a[1];render();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.leftMargin=dp(3);p.rightMargin=dp(3);l.addView(b,p);}body.addView(l);gap(12);}
 void detail(){if(current==null){go("home");return;}tabs();addText(current.optString("tradition"),12,true,ORANGE);h1(current.optString("title"));sourceLine(current);
  if(tab.equals("story")){small(current.optString("source_kind")+" · retold in simple English");para(current.optString("story"));h2("Why this fits");para(current.optString("why"));sourceLine(current);image("reading",150);action("The lesson",true,()->{tab="lesson";render();});}
  else if(tab.equals("lesson")){addText(current.optString("uplift"),23,true,INK);small("Original lesson based on the source, not a quoted verse.");h2("From the source");para(current.optString("teaching"));sourceLine(current);h2("For your situation");para(current.optString("application"));sourceLine(current);action("Try this",true,()->{tab="step";render();});}
  else{h2("One practical step");LinearLayout box=vertical();box.setPadding(dp(16),dp(14),dp(16),dp(14));box.setBackground(bg(SOFT,0,15));box.addView(text(current.optString("step"),18,false,INK));body.addView(box);sourceLine(current);small("This is an application for today, not an instruction quoted from the book.");image("walking",160);action("Other stories",true,()->go("results"));}
  action("Source",false,()->go("source"));action("Share",false,()->go("share"));}
 void source(){if(current==null)return;h1(current.optString("book"));para(current.optString("reference"));small(current.optString("source_kind"));h2("The episode");para(current.optString("title"));h2("What is sourced");para("The retelling describes the episode or teaching named above. The explanation, personal comparison and practical step are written separately by EverSage.");small("Section numbering can differ between editions. Named episodes are included to help identify the passage.");String url=current.optString("source_url");if(!url.isEmpty()){small(url);action("Read online",false,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("No browser is available.");}});}action("Copy ref",false,()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Source",current.optString("book")+" · "+current.optString("reference")));toast("Reference copied.");});}
 void traditionPicker(){h1("Choose traditions");small("Only relevant reviewed entries from your choices will be shown. A missing match leads to a question, not a random result.");CheckBox all=new CheckBox(this);all.setText("All available traditions");all.setTextSize(16*textScale);all.setTextColor(INK);all.setMinHeight(dp(52));all.setChecked(chosen.isEmpty());body.addView(all);all.setOnClickListener(v->{chosen.clear();render();});for(String t:traditions){CheckBox b=new CheckBox(this);b.setText(t);b.setTextColor(INK);b.setTextSize(16*textScale);b.setMinHeight(dp(52));b.setChecked(chosen.contains(t));body.addView(b);b.setOnCheckedChangeListener((v,yes)->{if(yes)chosen.add(t);else chosen.remove(t);all.setChecked(chosen.isEmpty());});}action("Apply",true,()->{prefs.edit().putStringSet("traditions",new HashSet<>(chosen)).apply();onBackPressed();});}
 JSONObject findById(String id){for(JSONObject c:cases)if(c.optString("id").equals(id))return c;return null;}
 void toggleSave(){if(current==null)return;String id=current.optString("id");if(!saved.add(id)){saved.remove(id);toast("Removed from saved.");}else toast("Story saved.");prefs.edit().putStringSet("saved",new HashSet<>(saved)).apply();render();}
 void saved(){h1("Saved stories");small("Stored on this phone. No cloud account.");int count=0;for(JSONObject c:cases)if(saved.contains(c.optString("id"))){count++;option(c.optString("title"),c.optString("book")+" · "+c.optString("reference"),()->{current=c;tab="story";go("detail");});}if(count==0){image("reading",170);para("Save a story with the Save button to return to it here.");action("Explore",true,()->go("home"));}}
 void selectDaily(boolean next){ArrayList<JSONObject> pool=new ArrayList<>();for(JSONObject c:cases)if(chosen.isEmpty()||chosen.contains(c.optString("tradition")))pool.add(c);if(pool.isEmpty())return;int index=0;if(next&&current!=null){index=pool.indexOf(current)+1;}else{Calendar d=Calendar.getInstance();index=Math.floorMod(d.get(Calendar.YEAR)*367+d.get(Calendar.DAY_OF_YEAR),pool.size());}current=pool.get(index%pool.size());}
 void daily(){if(current==null)selectDaily(false);h1("Today’s story");small("A reading choice for today, not a match to a personal problem.");image("home",170);if(current==null)return;addText(current.optString("uplift"),23,true,INK);sourceLine(current);small("Original insight from this source episode.");action("Read story",true,()->{tab="story";go("detail");});action("Another",false,()->{selectDaily(true);render();});}
 void library(){h1("Sources & episodes");small(cases.size()+" distinct entries across "+traditions.size()+" tradition groups. This is a growing, bounded collection, not all of world scripture.");for(String t:traditions){h2(t);for(JSONObject c:cases)if(c.optString("tradition").equals(t))option(c.optString("title"),c.optString("book")+" · "+c.optString("reference"),()->{current=c;tab="story";go("detail");});}}
 void settings(){h1("Settings");h2("Reading size");LinearLayout l=row();for(String[] a:new String[][]{{"Normal","1"},{"Large","1.2"}}){Button b=button(a[0],Math.abs(textScale-Float.parseFloat(a[1]))<.01,()->{textScale=Float.parseFloat(a[1]);prefs.edit().putFloat("textScale",textScale).apply();render();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.leftMargin=dp(4);p.rightMargin=dp(4);l.addView(b,p);}body.addView(l);filter();h2("Daily reading");Switch sw=new Switch(this);sw.setText("Daily reminder");sw.setTextColor(INK);sw.setTextSize(16*textScale);sw.setMinHeight(dp(52));sw.setChecked(prefs.getBoolean("reminder",false));body.addView(sw);sw.setOnCheckedChangeListener((v,b)->scheduleReminder(b,prefs.getString("time","08:00")));action("Set time",false,()->{String[] t=prefs.getString("time","08:00").split(":");new TimePickerDialog(this,(v,h,m)->{String time=String.format(Locale.ROOT,"%02d:%02d",h,m);prefs.edit().putString("time",time).apply();if(prefs.getBoolean("reminder",false))scheduleReminder(true,time);toast("Reminder time: "+time);},Integer.parseInt(t[0]),Integer.parseInt(t[1]),false).show();});small("Reminders may be delayed by phone power settings. Open the app after a phone restart to set them again.");h2("On this phone");para("Your writing is not saved as a history. Saved stories and preferences stay on this phone. No account or server is used.");action("Clear saved",false,()->new AlertDialog.Builder(this).setTitle("Clear saved stories?").setMessage("This removes the saved list on this phone.").setNegativeButton("Cancel",null).setPositiveButton("Clear",(d,w)->{saved.clear();prefs.edit().putStringSet("saved",new HashSet<>()).apply();toast("Saved list cleared.");}).show());action("Sources",false,()->go("library"));small("EverSage 0.3 · Native Android preview\nSource retellings and original applications are separate. This app uses specific offline matching, not an AI that can answer every possible problem.");}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 void scheduleReminder(boolean enabled,String time){if(enabled&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);prefs.edit().putBoolean("reminder",false).apply();toast("Allow notifications, then turn the reminder on again.");return;}String[] parts=time.split(":");AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);PendingIntent p=PendingIntent.getBroadcast(this,1,new Intent(this,DailyReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.cancel(p);if(enabled){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,Integer.parseInt(parts[0]));c.set(Calendar.MINUTE,Integer.parseInt(parts[1]));c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(Calendar.DATE,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);}prefs.edit().putBoolean("reminder",enabled).apply();}
 void shareScreen(){if(current==null)return;h1("Share a lesson");small("The card includes the book and reference. Your situation is not added.");cardPreview=new ImageView(this);cardPreview.setAdjustViewBounds(true);cardPreview.setContentDescription("Lesson image preview");body.addView(cardPreview,new LinearLayout.LayoutParams(-1,-2));CheckBox art=new CheckBox(this);art.setText("Include artwork");art.setTextColor(INK);art.setMinHeight(dp(52));art.setChecked(artOn);body.addView(art);art.setOnCheckedChangeListener((v,b)->{artOn=b;paintCard();});action("Share",true,()->writeCard(false));action("Save image",false,()->writeCard(true));paintCard();}
 void paintCard(){JSONObject c=current;boolean withArt=artOn;worker.execute(()->{Bitmap bitmap=makeCard(c,withArt);runOnUiThread(()->{if(!page.equals("share")){bitmap.recycle();return;}Bitmap old=card;card=bitmap;cardPreview.setImageBitmap(bitmap);});});}
 Bitmap makeCard(JSONObject c,boolean art){Bitmap b=Bitmap.createBitmap(1080,1500,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(PAPER);if(art)try(InputStream in=getAssets().open("art/share.webp")){Bitmap bg=BitmapFactory.decodeStream(in);canvas.drawBitmap(bg,null,new Rect(0,0,1080,1500),new Paint(3));bg.recycle();}catch(Exception ignored){}Paint p=new Paint(3);p.setColor(INK);p.setTypeface(Typeface.create("serif",0));p.setTextSize(49);float y=words(canvas,p,c.optString("uplift"),90,550,900,72);p.setColor(ORANGE);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(27);y=words(canvas,p,"Inspired by "+c.optString("book"),90,y+55,900,41);p.setTypeface(Typeface.create("sans-serif",0));p.setTextSize(24);words(canvas,p,c.optString("reference"),90,y+10,900,36);p.setColor(MUTED);p.setTextSize(23);canvas.drawText("EverSage lesson - not a quoted verse",90,1300,p);p.setColor(ORANGE);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(36);canvas.drawText("eversage",90,1410,p);return b;}
 float words(Canvas c,Paint p,String text,float x,float y,float width,float height){String line="";for(String w:text.split("\\s+")){String next=line.isEmpty()?w:line+" "+w;if(!line.isEmpty()&&p.measureText(next)>width){c.drawText(line,x,y,p);y+=height;line=w;}else line=next;}if(!line.isEmpty()){c.drawText(line,x,y,p);y+=height;}return y;}
 void writeCard(boolean save){JSONObject c=current;boolean art=artOn;worker.execute(()->{try{Bitmap bitmap=makeCard(c,art);ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,bytes);bitmap.recycle();byte[] data=bytes.toByteArray();if(save&&Build.VERSION.SDK_INT>=29){ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"EverSage-"+System.currentTimeMillis()+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/EverSage");Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException();try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(data);}runOnUiThread(()->toast("Image saved in Pictures / EverSage."));}else if(save){pendingImage=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/png").putExtra(Intent.EXTRA_TITLE,"EverSage-lesson.png");runOnUiThread(()->startActivityForResult(i,12));}else{File dir=new File(getCacheDir(),"shared");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,"wisdom.png"))){out.write(data);}Uri uri=Uri.parse("content://app.eversage.offline.share/wisdom.png");Intent i=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("EverSage lesson",uri));runOnUiThread(()->startActivity(Intent.createChooser(i,"Share lesson")));}}catch(Exception e){runOnUiThread(()->toast("Could not save the image. Please try again."));}});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==12&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingImage!=null){Uri target=data.getData();byte[] bytes=pendingImage;pendingImage=null;worker.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(target)){out.write(bytes);runOnUiThread(()->toast("Image saved."));}catch(Exception e){runOnUiThread(()->toast("Could not save the image."));}});}}
}
